 10| // ─── Global State ──────────────────────────────────────
 11| 
 12| let shuttingDown = false;
 13| let abortController: AbortController | null = null;
 14| 
 15| function setupSignalHandlers(): void {
 16|   const handler = () => {
 17|     if (shuttingDown) {
 18|       console.error(dim("\nForcing exit..."));
 19|       Deno.exit(1);
 20|     }
 21|     shuttingDown = true;
 22|     console.error(`\n${colorize("⚠", C.yellow)} ${bold("Interrupted. Finishing current operation...")}`);
 23|     console.error(dim("  Press Ctrl+C again to force exit."));
 24|     if (abortController) {
 25|       abortController.abort();
 26|     }
 27|   };
 28|   Deno.addSignalListener("SIGINT", handler);
 29|   Deno.addSignalListener("SIGTERM", handler);
 30| }
