 32| // ─── Restart Helper ────────────────────────────────────
 33| 
 34| async function performRestart(resumeFile: string): Promise<void> {
 35|   console.error(dim("  Spawning new CA process..."));
 36|   const child = new Deno.Command("deno", {
 37|     args: ["run", "-A", "ca.ts", "--resume", resumeFile],
 38|     cwd: Deno.cwd(),
 39|     stdin: "inherit",
 40|     stdout: "inherit",
 41|     stderr: "inherit",
 42|   }).spawn();
 43|   // Wait for the child to finish — keeps the foreground process group
 44|   // so the child can read from stdin without EIO errors
 45|   const status = await child.status;
 46|   Deno.exit(status.code);
 47| }
