120| async function interactive(existingMessages?: ChatMessage[]): Promise<void> {
121|   const config = getConfig();
122| 
123|   // Build initial system prompt
124|   const systemContent = await buildSystemContent(config, Deno.cwd());
125| 
126|   let messages: ChatMessage[];
127|   if (existingMessages) {
128|     messages = existingMessages;
129|     // Update system prompt with current config
130|     if (messages[0]?.role === "system") {
131|       messages[0].content = systemContent;
132|     }
133|   } else {
134|     messages = [
135|       { role: "system", content: systemContent },
136|     ];
137|   }
138| 
139|   printBanner(config);
140| 
141|   const encoder = new TextEncoder();
142|   const decoder = new TextDecoder();
143|   let stdinBuffer = "";
144| 
145|   async function readLine(promptStr: string): Promise<string | null> {
146|     const nlIndex = stdinBuffer.indexOf("\n");
147|     if (nlIndex !== -1) {
148|       const line = stdinBuffer.substring(0, nlIndex);
149|       stdinBuffer = stdinBuffer.substring(nlIndex + 1);
150|       return line.replace(/\r$/, "");
151|     }
152| 
153|     await Deno.stdout.write(encoder.encode(promptStr));
154| 
155|     const buf = new Uint8Array(4096);
156|     while (true) {
157|       const n = await Deno.stdin.read(buf);
158|       if (n === null) {
159|         if (stdinBuffer.length > 0) {
160|           const line = stdinBuffer;
161|           stdinBuffer = "";
162|           return line;
163|         }
164|         return null;
165|       }
166| 
167|       stdinBuffer += decoder.decode(buf.subarray(0, n));
168| 
169|       const nlIdx = stdinBuffer.indexOf("\n");
170|       if (nlIdx !== -1) {
171|         const line = stdinBuffer.substring(0, nlIdx);
172|         stdinBuffer = stdinBuffer.substring(nlIdx + 1);
173|         return line.replace(/\r$/, "");
174|       }
175|     }
176|   }
177| 
178|   // askUser callback for interactive mode
179|   async function askUserCallback(question: string): Promise<string> {
180|     console.error(`\n${colorize("💬", C.cyan)} ${bold("Agent asks:")} ${question}`);
181|     const answer = await readLine(`${colorize("❯❯ ", C.cyan)}`);
182|     return answer?.trim() ?? "";
183|   }
184| 
185|   // Multi-line input support
186|   async function readMultiLine(): Promise<string | null> {
187|     const lines: string[] = [];
188|     let firstLine = true;
189| 
190|     while (true) {
191|       const promptStr = firstLine
192|         ? colorize("❯ ", C.cyan)
193|         : colorize("│ ", dim(""));
194| 
195|       const line = await readLine(promptStr);
196|       firstLine = false;
197| 
198|       if (line === null) {
199|         // EOF
200|         return lines.length > 0 ? lines.join("\n") : null;
201|       }
202| 
203|       // Empty line on first prompt = skip
204|       if (lines.length === 0 && line.trim() === "") {
205|         return "";
206|       }
207| 
208|       // Check for termination: \e on its own line (backslash + 'e')
209|       if (line.trim() === "\\e") {
210|         return lines.join("\n");
211|       }
212| 
213|       lines.push(line);
214|     }
215|   }
216| 
217|   console.error(dim("Type \\e on a new line to submit multi-line input. /help for commands."));
218|   console.error("");
219| 
220|   while (true) {
221|     const input = await readMultiLine();
222|     if (input === null) break;
223| 
224|     const trimmed = input.trim();
225| 
226|     // Handle special commands
227|     if (trimmed.startsWith("/")) {
228|       const parts = trimmed.split(/\s+/);
229|       const cmd = parts[0].toLowerCase();
230|       const rest = parts.slice(1).join(" ");
231| 
232|       switch (cmd) {
233|         case "/upgrade": {
234|           console.error(`\n${colorize("🔄", C.cyan)} ${bold("Self-upgrade initiated...")}`);
235|           console.error(dim("  The agent will modify source files, then call restart_self."));
236|           console.error(dim("  Type /upgrade-go when ready, or just tell CA to upgrade itself."));
237|           continue;
238|         }
239| 
240|         case "/upgrade-go": {
241|           console.error(`\n${colorize("🔄", C.cyan)} ${bold("Running self-upgrade...")}`);
242|           const upgradePrompt = "You are asked to upgrade yourself. Read all ca_*.ts modules, analyze the codebase for improvements, implement them, run deno check and deno test to verify, and then call restart_self with confirm=true. Focus on: reducing code duplication, improving error handling, adding missing features, and making the code more robust. Be thorough.";
243|           try {
244|             const result = await run(upgradePrompt, messages, {
245|               config,
246|               askUser: askUserCallback,
247|             });
248|             messages = result.messages;
249|             if (result.needsRestart) {
250|               await performRestart(`${Deno.cwd()}/.ca_resume.json`);
251|             }
252|           } catch (e) {
253|             console.error(`\n${colorize("✘", C.red)} ${bold("Upgrade error:")} ${(e as Error).message}`);
254|           }
255|           continue;
256|         }
257| 
258|         case "/quit":
259|         case "/exit":
260|           console.error(colorize("Goodbye!", C.green));
261|           return;
262| 
263|         case "/help":
264|           console.error(`\n${bold("Commands:")}`);
265|           console.error(`  ${colorize("/help", C.cyan)}         ${dim("Show this help")}`);
266|           console.error(`  ${colorize("/history", C.cyan)}      ${dim("Show conversation history")}`);
267|           console.error(`  ${colorize("/clear", C.cyan)}        ${dim("Clear conversation (keeps system prompt)")}`);
268|           console.error(`  ${colorize("/model", C.cyan)}        ${dim("Show current model and config")}`);
269|           console.error(`  ${colorize("/system", C.cyan)}       ${dim("View or set system prompt (/system <text>)")}`);
270|           console.error(`  ${colorize("/context", C.cyan)}      ${dim("Refresh project context")}`);
271|           console.error(`  ${colorize("/save", C.cyan)} <file>  ${dim("Save conversation to file")}`);
272|           console.error(`  ${colorize("/load", C.cyan)} <file>  ${dim("Load conversation from file")}`);
273|           console.error(`  ${colorize("/edit", C.cyan)}         ${dim("Remove last exchange (user+assistant)")}`);
274|           console.error(`  ${colorize("/upgrade", C.cyan)}      ${dim("Initiate self-upgrade sequence")}`);
275|           console.error(`  ${colorize("/upgrade-go", C.cyan)}   ${dim("Execute self-upgrade now")}`);
276|           console.error(`  ${colorize("/tokens", C.cyan)}       ${dim("Estimate token usage")}`);
277|           console.error(`  ${colorize("/set", C.cyan)} <k> <v>  ${dim("Set config: maxRounds, maxRetries, maxTokens, temperature, ...")}`);
278|           console.error(`  ${colorize("/quit", C.cyan)}         ${dim("Exit")}`);
279|           console.error(`  ${colorize("/exit", C.cyan)}         ${dim("Exit")}`);
280|           console.error(`\n${dim("Multi-line: Type \\e on a new line to submit.")}`);
281|           console.error("");
282|           continue;
283| 
284|         case "/history": {
285|           const sep = separator();
286|           console.error(`\n${sep}`);
287|           console.error(bold("Conversation History"));
288|           console.error(sep);
289|           let msgIdx = 0;
290|           for (const msg of messages) {
291|             if (msg.role === "system") {
292|               const preview = (msg.content ?? "").length > 200
293|                 ? (msg.content ?? "").substring(0, 200) + dim("...")
294|                 : (msg.content ?? "");
295|               console.error(`\n${bold(colorize("system", C.cyan))}:`);
296|               console.error(`  ${dim(preview)}`);
297|               continue;
298|             }
299|             msgIdx++;
300|             const roleLabel = msg.role === "user"
301|               ? colorize(`[${msgIdx}] you`, C.green)
302|               : msg.role === "assistant"
303|               ? colorize(`[${msgIdx}] ca`, C.cyan)
304|               : colorize(`[${msgIdx}] ${msg.role}`, C.yellow);
305|             const content = msg.content ?? "";
306|             const preview = content.length > 300
307|               ? content.substring(0, 300) + dim("...")
308|               : content;
309|             console.error(`\n${bold(roleLabel)}:`);
310|             if (preview) console.error(`  ${dim(preview)}`);
311|             if (msg.tool_calls?.length) {
312|               for (const tc of msg.tool_calls) {
313|                 console.error(
314|                   `  ${colorize("→", C.magenta)} ${tc.function.name}(${dim(tc.function.arguments.substring(0, 120))})`,
315|                 );
316|               }
317|             }
318|           }
319|           console.error(`\n${sep}\n`);
320|           continue;
321|         }
322| 
323|         case "/clear":
324|           messages.length = 1; // keep system prompt
325|           console.error(colorize("Conversation cleared.", C.green));
326|           continue;
327| 
328|         case "/model": {
329|           const sep = separator("─", 40);
330|           console.error(`\n${sep}`);
331|           console.error(`${bold("Model:")} ${config.model}`);
332|           console.error(`${bold("API Base:")} ${config.apiBase}`);
333|           console.error(`${bold("Max tokens:")} ${config.maxTokens}`);
334|           console.error(`${bold("Max rounds:")} ${config.maxRounds}`);
335|           console.error(`${bold("Max retries:")} ${config.maxRetries}`);
336|           console.error(`${bold("Temperature:")} ${config.temperature}`);
337|           if (config.topP !== undefined) console.error(`${bold("Top P:")} ${config.topP}`);
338|           if (config.stop) console.error(`${bold("Stop:")} ${config.stop}`);
339|           if (config.responseFormat) console.error(`${bold("Response format:")} ${config.responseFormat}`);
340|           console.error(`${bold("Stream:")} ${config.stream ? "enabled" : "disabled"}`);
341|           console.error(`${bold("Thinking:")} ${config.thinking ? "enabled" : "disabled"}`);
342|           if (config.reasoningEffort) console.error(`${bold("Reasoning effort:")} ${config.reasoningEffort}`);
343|           console.error(`${bold("Sandbox:")} ${config.sandbox ? "enabled" : "disabled"}`);
344|           console.error(`${bold("Approve:")} ${config.approve ? "enabled" : "disabled"}`);
345|           console.error(`${bold("Dry run:")} ${config.dryRun ? "enabled" : "disabled"}`);
346|           console.error(`${bold("Tools:")} ${Object.entries(config.tools).filter(([, v]) => v).map(([k]) => k).join(", ")}`);
347|           console.error(`${sep}\n`);
348|           continue;
349|         }
350| 
351|         case "/system":
352|           if (rest) {
353|             // Set system prompt
354|             messages[0].content = rest;
355|             // Also update the config
356|             applyCliOverrides({ systemPrompt: rest });
357|             console.error(colorize("System prompt updated.", C.green));
358|           } else {
359|             // View system prompt
360|             const sep = separator();
361|             console.error(`\n${sep}`);
362|             console.error(bold("System Prompt:"));
363|             console.error(dim(messages[0].content ?? "(none)"));
364|             console.error(`${sep}\n`);
365|           }
366|           continue;
367| 
368|         case "/context":
369|           try {
370|             const newSystemContent = await buildSystemContent(config, Deno.cwd());
371|             messages[0].content = newSystemContent;
372|             console.error(colorize("Project context refreshed.", C.green));
373|           } catch (e) {
374|             console.error(`${colorize("✘", C.red)} Failed: ${(e as Error).message}`);
375|           }
376|           continue;
377| 
378|         case "/save":
379|           if (!rest) {
380|             console.error(`${colorize("✘", C.red)} Usage: /save <filepath>`);
381|             continue;
382|           }
383|           try {
384|             await saveConversation(messages, rest);
385|           } catch (e) {
386|             console.error(`${colorize("✘", C.red)} Save failed: ${(e as Error).message}`);
387|           }
388|           continue;
389| 
390|         case "/load":
391|           if (!rest) {
392|             console.error(`${colorize("✘", C.red)} Usage: /load <filepath>`);
393|             continue;
394|           }
395|           try {
396|             const loaded = await loadConversation(rest);
397|             messages.length = 0;
398|             messages.push(...loaded);
399|             // Update system prompt with current config
400|             if (messages[0]?.role === "system") {
401|               messages[0].content = systemContent;
402|             }
403|             console.error(colorize(`Loaded ${loaded.length} messages.`, C.green));
404|           } catch (e) {
405|             console.error(`${colorize("✘", C.red)} Load failed: ${(e as Error).message}`);
406|           }
407|           continue;
408| 
409|         case "/edit": {
410|           // Remove last user message and assistant response(s)
411|           let lastUserIdx = -1;
412|           for (let i = messages.length - 1; i >= 0; i--) {
413|             if (messages[i].role === "user") {
414|               lastUserIdx = i;
415|               break;
416|             }
417|           }
418|           if (lastUserIdx >= 0) {
419|             const removed = messages.splice(lastUserIdx);
420|             console.error(
421|               colorize(`Removed ${removed.length} messages (last user exchange).`, C.green),
422|             );
423|           } else {
424|             console.error(`${colorize("✘", C.red)} No user messages to remove.`);
425|           }
426|           continue;
427|         }
428| 
429|         case "/tokens": {
430|           const { estimateMessagesTokens } = await import("./ca_client.ts");
431|           const est = estimateMessagesTokens(messages);
432|           const pct = ((est / config.maxTokens) * 100).toFixed(1);
433|           console.error(
434|             `${bold("Estimated tokens:")} ~${est} / ${config.maxTokens} (${pct}%)`,
435|           );
436|           continue;
437|         }
438| 
439|         case "/set": {
440|           const setParts = rest.split(/\s+/);
441|           const key = setParts[0];
442|           const val = setParts[1];
443| 
444|           if (!key || val === undefined) {
445|             console.error(`${colorize("✘", C.red)} Usage: /set <key> <value>`);
446|             console.error(dim("  Keys: maxRounds, maxRetries, maxTokens, temperature,"));
447|             console.error(dim("        topP, stream (on/off), thinking (on/off),"));
448|             console.error(dim("        approve (on/off), dryRun (on/off), sandbox (on/off),"));
449|             console.error(dim("        autoCommit (on/off)"));
450|             continue;
451|           }
452| 
453|           const boolKeys = ["stream", "thinking", "approve", "dryRun", "sandbox", "autoCommit"];
454|           const numKeys = ["maxRounds", "maxRetries", "maxTokens", "temperature", "topP"];
455| 
456|           if (boolKeys.includes(key)) {
457|             const on = val === "on" || val === "1" || val === "true";
458|             (config as any)[key] = on;
459|             applyCliOverrides({ [key]: on } as any);
460|             console.error(colorize(`${key} = ${on ? "on" : "off"}`, C.green));
461|           } else if (numKeys.includes(key)) {
462|             const num = parseFloat(val);
463|             if (isNaN(num)) {
464|               console.error(`${colorize("✘", C.red)} ${key} requires a number.`);
465|               continue;
466|             }
467|             // temperature and topP are floats, others are ints
468|             const finalVal = (key === "temperature" || key === "topP") ? num : Math.floor(num);
469|             (config as any)[key] = finalVal;
470|             applyCliOverrides({ [key]: finalVal } as any);
471|             console.error(colorize(`${key} = ${finalVal}`, C.green));
472|           } else {
473|             console.error(`${colorize("✘", C.red)} Unknown key: ${key}`);
474|             console.error(dim("  Valid keys: maxRounds, maxRetries, maxTokens, temperature,"));
475|             console.error(dim("             topP, stream, thinking, approve, dryRun,"));
476|             console.error(dim("             sandbox, autoCommit"));
477|           }
478|           continue;
479|         }
480| 
481|         default:
482|           console.error(
483|             `${colorize("✘", C.red)} Unknown command: ${trimmed}. ${dim("Type /help for available commands.")}`,
484|           );
485|           continue;
486|       }
487|     }
488| 
489|     // Shell passthrough: !cmd runs directly without agent
490|     if (trimmed.startsWith("!")) {
491|       const shellCmd = trimmed.substring(1).trim();
492|       if (shellCmd) {
493|         console.error(dim(`! ${shellCmd}`));
494|         try {
495|           const proc = new Deno.Command("bash", {
496|             args: ["-c", shellCmd],
497|             cwd: Deno.cwd(),
498|             stdout: "inherit",
499|             stderr: "inherit",
500|           });
501|           const { code } = await proc.output();
502|           if (code !== 0) console.error(dim(`[exit: ${code}]`));
503|         } catch (e) {
504|           console.error(`${colorize("✘", C.red)} ${(e as Error).message}`);
505|         }
506|       }
507|       continue;
508|     }
509| 
510|     if (!trimmed) continue;
511| 
512|     // Run the agent with the current message
513|     abortController = new AbortController();
514|     try {
515|       const result = await run(trimmed, messages, {
516|         config,
517|         askUser: askUserCallback,
518|         signal: abortController.signal,
519|       });
520|       messages = result.messages;
521|       if (result.needsRestart) {
522|         await performRestart(`${Deno.cwd()}/.ca_resume.json`);
523|       }
524|     } catch (e) {
525|       console.error(
526|         `\n${colorize("✘", C.red)} ${bold("Error:")} ${(e as Error).message}`,
527|       );
528|     } finally {
529|       abortController = null;
