536| async function main(): Promise<void> {
537|   setupSignalHandlers();
538|   const args = Deno.args;
539|   let promptParts: string[] = [];
540|   let interactiveMode = false;
541|   const cliOverrides: Partial<AgentConfig> = {};
542|   let i = 0;
543| 
544|   while (i < args.length) {
545|     const a = args[i];
546|     if (a === "-h" || a === "--help") {
547|       help();
548|       Deno.exit(0);
549|     } else if (a === "-v" || a === "--version") {
550|       console.log(`CA ${VERSION}`);
551|       Deno.exit(0);
552|     } else if (a === "-i" || a === "--interactive") {
553|       interactiveMode = true;
554|       i++;
555|     } else if ((a === "-m" || a === "--model") && args[i + 1]) {
556|       cliOverrides.model = args[++i];
557|       i++;
558|     } else if (a === "--api-base" && args[i + 1]) {
559|       cliOverrides.apiBase = args[++i];
560|       i++;
561|     } else if (a === "--api-key" && args[i + 1]) {
562|       cliOverrides.apiKey = args[++i];
563|       i++;
564|     } else if (a === "--max-tokens" && args[i + 1]) {
565|       cliOverrides.maxTokens = parseInt(args[++i]);
566|       i++;
567|     } else if (a === "--max-rounds" && args[i + 1]) {
568|       cliOverrides.maxRounds = parseInt(args[++i]);
569|       i++;
570|     } else if (a === "--max-retries" && args[i + 1]) {
571|       cliOverrides.maxRetries = parseInt(args[++i]);
572|       i++;
573|     } else if (a === "--temperature" && args[i + 1]) {
574|       cliOverrides.temperature = parseFloat(args[++i]);
575|       i++;
576|     } else if (a === "--top-p" && args[i + 1]) {
577|       cliOverrides.topP = parseFloat(args[++i]);
578|       i++;
579|     } else if (a === "--stop" && args[i + 1]) {
580|       cliOverrides.stop = args[++i];
581|       i++;
582|     } else if (a === "--response-format" && args[i + 1]) {
583|       cliOverrides.responseFormat = args[++i];
584|       i++;
585|     } else if (a === "--logprobs") {
586|       cliOverrides.logprobs = true;
587|       i++;
588|     } else if (a === "--top-logprobs" && args[i + 1]) {
589|       cliOverrides.topLogprobs = parseInt(args[++i]);
590|       i++;
591|     } else if (a === "--user-id" && args[i + 1]) {
592|       cliOverrides.userId = args[++i];
593|       i++;
594|     } else if (a === "--stream") {
595|       cliOverrides.stream = true;
596|       i++;
597|     } else if (a === "--thinking") {
598|       cliOverrides.thinking = true;
599|       i++;
600|     } else if (a === "--reasoning-effort" && args[i + 1]) {
601|       cliOverrides.reasoningEffort = args[++i];
602|       i++;
603|     } else if (a === "--system-prompt" && args[i + 1]) {
604|       cliOverrides.systemPromptFile = args[++i];
605|       i++;
606|     } else if (a === "--sandbox") {
607|       cliOverrides.sandbox = true;
608|       i++;
609|     } else if (a === "--no-sandbox") {
610|       cliOverrides.sandbox = false;
611|       i++;
612|     } else if (a === "--approve") {
613|       cliOverrides.approve = true;
614|       i++;
615|     } else if (a === "--resume" && args[i + 1]) {
616|       cliOverrides.resumeFile = args[++i];
617|       i++;
618|     } else if (a === "--no-auto-commit") {
619|       cliOverrides.autoCommit = false;
620|       i++;
621|     } else if (a === "--auto-commit") {
622|       cliOverrides.autoCommit = true;
623|       i++;
624|     } else if (a === "--dry-run") {
625|       cliOverrides.dryRun = true;
626|       i++;
627|     } else {
628|       promptParts.push(a);
629|       i++;
630|     }
631|   }
632| 
633|   // Initialize configuration (env -> file -> CLI)
634|   await initConfig(cliOverrides);
635|   const config = getConfig();
636| 
637|   // Resume from saved conversation
638|   if (config.resumeFile) {
639|     console.error(`${colorize("📂", C.cyan)} ${bold("Resuming conversation...")}`);
640|     try {
641|       const msgs = await loadConversation(config.resumeFile);
642|       const systemContent = await buildSystemContent(config, Deno.cwd());
643|       if (msgs[0]?.role === "system") {
644|         msgs[0].content = systemContent;
645|       }
646|       console.error(colorize("📂 Conversation resumed. Continue where you left off.", C.green));
647|       console.error("");
648|       await interactive(msgs);
649|       return;
650|     } catch (e) {
651|       console.error(`${colorize("✘", C.red)} ${bold("Resume failed:")} ${(e as Error).message}`);
652|       Deno.exit(1);
653|     }
654|   }
655| 
656|   // Interactive mode
657|   if (interactiveMode) {
658|     const isLocal = config.apiBase.includes("localhost") ||
659|       config.apiBase.includes("127.0.0.1");
660|     if (!config.apiKey && !isLocal) {
661|       console.error(
662|         `${colorize("✘", C.red)} ${bold("Error:")} CA_API_KEY not set. Use --api-key, CA_API_KEY env, or a local API base.`,
663|       );
664|       Deno.exit(1);
665|     }
666|     await interactive();
667|     return;
668|   }
669| 
670|   // Single-shot mode
671|   const prompt = promptParts.join(" ").trim();
672|   if (!prompt) {
673|     console.error(
674|       `${colorize("✘", C.red)} ${bold("Error:")} No prompt. Use -h for help, or -i for interactive mode.`,
675|     );
676|     Deno.exit(1);
677|   }
678| 
679|   const isLocal = config.apiBase.includes("localhost") ||
680|     config.apiBase.includes("127.0.0.1");
681|   if (!config.apiKey && !isLocal) {
682|     console.error(
683|       `${colorize("✘", C.red)} ${bold("Error:")} CA_API_KEY not set. Use --api-key, CA_API_KEY env, or a local API base.`,
684|     );
685|     Deno.exit(1);
686|   }
687| 
688|   const result = await run(prompt, undefined, { config });
689|   if (result.needsRestart) {
690|     await performRestart(`${Deno.cwd()}/.ca_resume.json`);
691|   }
692| }
693| 
694| main().catch((e) => {
695|   console.error(`\n${colorize("✘", C.red)} ${bold("Fatal:")} ${(e as Error).message}`);
696|   Deno.exit(1);
