 48| function loadEnv(): Partial<AgentConfig> {
 49|   const out: Partial<AgentConfig> = {};
 50| 
 51|   const s = (key: string) => Deno.env.get(key);
 52|   const b = (key: string) => s(key) === "1" || s(key) === "true";
 53|   const n = (key: string) => s(key) ? parseInt(s(key)!) : undefined;
 54|   const f = (key: string) => s(key) ? parseFloat(s(key)!) : undefined;
 55| 
 56|   if (s("CA_MODEL")) out.model = s("CA_MODEL")!;
 57|   if (s("CA_API_KEY")) out.apiKey = s("CA_API_KEY")!;
 58|   if (s("CA_API_BASE")) out.apiBase = s("CA_API_BASE")!.replace(/\/+$/, "");
 59|   if (n("CA_MAX_TOKENS")) out.maxTokens = n("CA_MAX_TOKENS")!;
 60|   if (n("CA_MAX_ROUNDS")) out.maxRounds = n("CA_MAX_ROUNDS")!;
 61|   if (n("CA_MAX_RETRIES")) out.maxRetries = n("CA_MAX_RETRIES")!;
 62|   if (f("CA_TEMPERATURE") !== undefined) out.temperature = f("CA_TEMPERATURE")!;
 63|   if (f("CA_TOP_P") !== undefined) out.topP = f("CA_TOP_P")!;
 64|   if (s("CA_STOP")) out.stop = s("CA_STOP")!;
 65|   if (s("CA_RESPONSE_FORMAT")) out.responseFormat = s("CA_RESPONSE_FORMAT")!;
 66|   if (b("CA_LOGPROBS")) out.logprobs = true;
 67|   if (n("CA_TOP_LOGPROBS")) out.topLogprobs = n("CA_TOP_LOGPROBS")!;
 68|   if (s("CA_USER_ID")) out.userId = s("CA_USER_ID")!;
 69|   if (b("CA_THINKING")) out.thinking = true;
 70|   if (s("CA_REASONING_EFFORT")) out.reasoningEffort = s("CA_REASONING_EFFORT")!;
 71|   if (b("CA_STREAM")) out.stream = true;
 72|   if (b("CA_SANDBOX")) out.sandbox = true;
 73|   if (s("CA_SANDBOX") === "0" || s("CA_SANDBOX") === "false") out.sandbox = false;
 74|   if (b("CA_APPROVE")) out.approve = true;
 75|   if (b("CA_DRY_RUN")) out.dryRun = true;
