 78|   if (s("CA_SYSTEM_PROMPT")) out.systemPrompt = s("CA_SYSTEM_PROMPT")!;
 79|   if (s("CA_SYSTEM_PROMPT_FILE")) out.systemPromptFile = s("CA_SYSTEM_PROMPT_FILE")!;
