 84| // ─── Load .ca.json ─────────────────────────────────────
 85| 
 86| async function loadCaJson(): Promise<Partial<AgentConfig>> {
 87|   const cwd = Deno.cwd();
 88|   // Walk up directories to find .ca.json
 89|   const parts = cwd.split("/").filter(Boolean);
 90|   const searchPaths: string[] = [];
 91|   for (let i = parts.length; i >= 0; i--) {
 92|     searchPaths.push("/" + parts.slice(0, i).join("/") + "/.ca.json");
 93|   }
 94|   // Also check XDG config
 95|   const xdgHome = Deno.env.get("XDG_CONFIG_HOME") ?? (Deno.env.get("HOME") ?? "/home") + "/.config";
 96|   searchPaths.push(xdgHome + "/ca/config.json");
 97| 
 98|   for (const path of searchPaths) {
 99|     try {
100|       const raw = await Deno.readTextFile(path);
101|       const parsed: CaJsonConfig = JSON.parse(raw);
102|       return caJsonToConfig(parsed);
103|     } catch {
104|       // File doesn't exist or can't parse, continue
105|     }
106|   }
107| 
108|   return {};
109| }
