111| function caJsonToConfig(json: CaJsonConfig): Partial<AgentConfig> {
112|   const out: Partial<AgentConfig> = {};
113| 
114|   if (json.model) out.model = json.model;
115|   if (json.api_key) out.apiKey = json.api_key;
116|   if (json.api_base) out.apiBase = json.api_base.replace(/\/+$/, "");
117|   if (json.max_tokens) out.maxTokens = json.max_tokens;
118|   if (json.max_rounds) out.maxRounds = json.max_rounds;
119|   if (json.max_retries !== undefined) out.maxRetries = json.max_retries;
120|   if (json.temperature !== undefined) out.temperature = json.temperature;
121|   if (json.top_p !== undefined) out.topP = json.top_p;
122|   if (json.stop) out.stop = json.stop;
123|   if (json.response_format) out.responseFormat = json.response_format;
124|   if (json.logprobs !== undefined) out.logprobs = json.logprobs;
125|   if (json.top_logprobs !== undefined) out.topLogprobs = json.top_logprobs;
126|   if (json.user_id) out.userId = json.user_id;
127|   if (json.thinking !== undefined) out.thinking = json.thinking;
128|   if (json.reasoning_effort) out.reasoningEffort = json.reasoning_effort;
129|   if (json.stream !== undefined) out.stream = json.stream;
130|   if (json.sandbox !== undefined) out.sandbox = json.sandbox;
131|   if (json.approve !== undefined) out.approve = json.approve;
132|   if (json.auto_commit !== undefined) out.autoCommit = json.auto_commit;
133|   if (json.system_prompt) out.systemPrompt = json.system_prompt;
134|   if (json.tools) {
135|     out.tools = { ...DEFAULTS.tools, ...json.tools };
136|   }
137| 
138|   return out;
139| }
