154| export function validateConfig(config: AgentConfig): string[] {
155|   const warnings: string[] = [];
156|   if (config.temperature < 0 || config.temperature > 2) {
157|     warnings.push(`Temperature ${config.temperature} is outside typical range 0-2`);
158|   }
159|   if (config.maxTokens < 100) {
160|     warnings.push(`maxTokens (${config.maxTokens}) is very low`);
161|   }
162|   if (config.maxRounds < 1) {
163|     warnings.push(`maxRounds (${config.maxRounds}) must be >= 1`);
164|   }
165|   if (config.maxRetries < 0) {
166|     warnings.push(`maxRetries (${config.maxRetries}) must be >= 0`);
167|   }
168|   if (config.topP !== undefined && (config.topP < 0 || config.topP > 1)) {
169|     warnings.push(`topP (${config.topP}) must be between 0 and 1`);
170|   }
171|   if (config.topLogprobs !== undefined && (config.topLogprobs < 0 || config.topLogprobs > 20)) {
172|     warnings.push(`topLogprobs (${config.topLogprobs}) exceeds typical max of 20`);
173|   }
174|   return warnings;
175| }
