177| export async function initConfig(cliOverrides: Partial<AgentConfig>): Promise<void> {
178|   // Load in priority order (later overrides earlier):
179|   // 1. Defaults
180|   _config = { ...DEFAULTS, tools: { ...DEFAULTS.tools } };
181| 
182|   // 2. .ca.json file
183|   const fileConfig = await loadCaJson();
184|   applyConfig(fileConfig);
185| 
186|   // 3. Environment variables
187|   const envConfig = loadEnv();
188|   applyConfig(envConfig);
189| 
190|   // 4. CLI arguments
191|   applyCliOverrides(cliOverrides);
192| 
193|   // 5. Load system prompt from file if specified
194|   if (_config.systemPromptFile) {
195|     try {
196|       _config.systemPrompt = await Deno.readTextFile(_config.systemPromptFile);
197|     } catch {
198|       console.error(`Warning: Could not read system prompt file: ${_config.systemPromptFile}`);
199|     }
200|   }
201| 
202|   // 6. Validate
203|   const warnings = validateConfig(_config);
204|   for (const w of warnings) {
205|     console.error(`Warning: ${w}`);
206|   }
207| }
