 57| // ─── Project Context ───────────────────────────────────
 58| 
 59| export async function buildSystemContent(config: AgentConfig, cwd: string): Promise<string> {
 60|   const systemPrompt = buildSystemPrompt(config);
 61|   let contextStr = "";
 62|   try {
 63|     contextStr = await getProjectContext(cwd);
 64|   } catch { /* non-critical */ }
 65|   return contextStr
 66|     ? systemPrompt + `\n\nProject context:\n${contextStr}`
 67|     : systemPrompt;
 68| }
