 70| export async function getProjectContext(cwd: string): Promise<string> {
 71|   const parts: string[] = [];
 72|   parts.push(`Working directory: ${cwd}`);
 73| 
 74|   // Git info
 75|   try {
 76|     const gitBranch = new Deno.Command("git", {
 77|       args: ["branch", "--show-current"],
 78|       cwd,
 79|       stdout: "piped",
 80|       stderr: "piped",
 81|     });
 82|     const { stdout: branchOut } = await gitBranch.output();
 83|     const branch = new TextDecoder().decode(branchOut).trim();
 84|     if (branch) parts.push(`Git branch: ${branch}`);
 85| 
 86|     const gitStatus = new Deno.Command("git", {
 87|       args: ["status", "--short"],
 88|       cwd,
 89|       stdout: "piped",
 90|       stderr: "piped",
 91|     });
 92|     const { stdout: statusOut } = await gitStatus.output();
 93|     const status = new TextDecoder().decode(statusOut).trim();
 94|     if (status) {
 95|       const changedFiles = status.split("\n").slice(0, 15);
 96|       parts.push(`Changed files:\n${changedFiles.join("\n")}`);
 97|     }
 98|   } catch { /* not a git repo */ }
 99| 
100|   // Directory overview
101|   try {
102|     const entries: string[] = [];
103|     for await (const entry of Deno.readDir(cwd)) {
104|       if (entry.name.startsWith(".")) continue;
105|       const icon = entry.isDirectory ? "/" : "";
106|       entries.push(`  ${entry.name}${icon}`);
107|     }
108|     if (entries.length > 0 && entries.length <= 30) {
109|       parts.push(`Top-level directory:\n${entries.sort().join("\n")}`);
110|     }
111|   } catch { /* can't read dir */ }
112| 
113|   // Language detection
114|   try {
115|     const exts = new Map<string, number>();
116|     for await (const entry of Deno.readDir(cwd)) {
117|       if (entry.isFile) {
118|         const ext = entry.name.includes(".") ? entry.name.split(".").pop() ?? "" : "";
119|         if (ext && ext.length < 10) {
120|           exts.set(ext, (exts.get(ext) ?? 0) + 1);
121|         }
122|       }
123|     }
124|     if (exts.size > 0) {
125|       const sorted = [...exts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6);
126|       parts.push(`File types: ${sorted.map(([ext, count]) => `.${ext}(${count})`).join(", ")}`);
127|     }
128|   } catch { /* can't scan */ }
129| 
130|   return parts.join("\n");
131| }
