133| // ─── Agent Loop ────────────────────────────────────────
134| 
135| export interface AgentOptions {
136|   config: AgentConfig;
137|   askUser?: AskUserCallback;
138|   signal?: AbortSignal;
139| }
140| 
141| export interface RunResult {
142|   messages: ChatMessage[];
143|   needsRestart: boolean;
144| }
145| 
146| export async function run(
147|   prompt: string,
148|   messages?: ChatMessage[],
149|   opts?: AgentOptions,
150| ): Promise<RunResult> {
151|   const config = opts?.config!;
152|   const askUser = opts?.askUser;
153|   const tools = buildToolDefs(config);
154|   const systemContent = await buildSystemContent(config, Deno.cwd());
155| 
156|   const msgs = messages ?? [
157|     { role: "system" as const, content: systemContent },
158|   ];
159| 
160|   // Update system prompt if messages already have one
161|   if (messages && messages.length > 0 && messages[0].role === "system") {
162|     messages[0].content = systemContent;
163|   }
164| 
165|   // Add the user message
166|   msgs.push({ role: "user", content: prompt });
167| 
168|   const spinner = new Spinner();
169|   let totalTokens = estimateMessagesTokens(msgs);
170| 
171|   for (let round = 1; round <= config.maxRounds; round++) {
172|     // Check for abort signal
173|     if (opts?.signal?.aborted) {
174|       console.error(`\n${colorize("⚠", dim(""))} Aborted by signal.`);
175|       break;
176|     }
177| 
178|     // Token budget check
179|     const estTokens = estimateMessagesTokens(msgs);
180|     if (estTokens > config.maxTokens * 0.85) {
181|       console.error(
182|         `${colorize("⚠", dim(""))} ${bold("Token budget warning:")} ~${estTokens} estimated tokens (${((estTokens / config.maxTokens) * 100).toFixed(0)}% of ${config.maxTokens})`,
183|       );
184|     }
185|     if (estTokens > config.maxTokens) {
186|       console.error(
187|         `${colorize("✘", dim(""))} ${bold("Token budget exceeded:")} ~${estTokens} > ${config.maxTokens} max`,
188|       );
189|       break;
190|     }
191| 
192|     spinner.start(`Round ${round}/${config.maxRounds} — ${config.model}`);
193| 
194|     let response: ChatMessage;
195|     let usage;
196|     try {
197|       const result = await chatCompletion(msgs, tools, config);
198|       response = result.message;
199|       usage = result.usage;
200|       if (usage) {
201|         totalTokens += usage.totalTokens;
202|       }
203|     } catch (e) {
204|       spinner.fail(`API error: ${(e as Error).message}`);
205|       throw e;
206|     }
207| 
208|     msgs.push(response);
209| 
210|     if (response.tool_calls?.length) {
211|       spinner.stop();
212| 
213|       // Execute tools in parallel
214|       const toolResults = await Promise.all(
215|         response.tool_calls.map(async (tc) => {
216|           const name = tc.function.name;
217|           let args: Record<string, unknown> = {};
218|           try {
219|             args = JSON.parse(tc.function.arguments);
220|           } catch {
221|             console.error(
222|               `${colorize("⚠", dim(""))} Failed to parse arguments for ${name}`,
223|             );
224|             return {
225|               tc,
226|               result: `Error: Invalid JSON arguments: ${tc.function.arguments.substring(0, 200)}`,
227|             };
228|           }
229| 
230|           // Pretty print
231|           console.error(`\n${formatToolCall(name, args)}`);
232| 
233|           const result = await executeTool(name, args, {
234|             sandbox: config.sandbox,
235|             approve: config.approve,
236|             dryRun: config.dryRun,
237|             autoCommit: config.autoCommit,
238|             cwd: Deno.cwd(),
239|             askUser,
240|           });
241| 
242|           console.error(formatToolResult(result.output));
243| 
244|           return { tc, result: result.output };
245|         }),
246|       );
247| 
248|       // Check for errors and collect
249|       let hasErrors = false;
250|       for (const { tc, result } of toolResults) {
251|         msgs.push({
252|           role: "tool",
253|           tool_call_id: tc.id,
254|           content: result,
255|         });
256|         if (result.startsWith("Error") || result.startsWith("Error:")) {
257|           hasErrors = true;
258|         }
259|       }
260| 
261|       // Check for restart signal
262|       for (const { result } of toolResults) {
263|         if (result === "RESTART_READY") {
264|           spinner.stop();
265|           console.error(`\n${colorize("🔄", C.cyan)} ${bold("Restarting with new version...")}`);
266|           const resumeFile = `${Deno.cwd()}/.ca_resume.json`;
267|           await saveConversation(msgs, resumeFile);
268|           return { messages: msgs, needsRestart: true };
269|         }
270|       }
271| 
272|       // If there were errors, add a hint for the model
273|       if (hasErrors) {
274|         console.error(
275|           `  ${colorize("⚠", dim(""))} Some tool calls returned errors — model will attempt recovery`,
276|         );
277|         // Errors are already in the tool messages, model can recover automatically
278|       }
279| 
280|       console.error(""); // blank line between rounds
281| 
282|       // If in dry-run mode, stop after one round
283|       if (config.dryRun) {
284|         spinner.succeed("Dry-run complete (1 round)");
285|         return { messages: msgs, needsRestart: false };
286|       }
287|     } else {
288|       // No tool calls — final response
289|       spinner.succeed(`Done (${round} round${round > 1 ? "s" : ""})`);
290|       if (response.content) {
291|         console.log(response.content);
292|       }
293|       return { messages: msgs, needsRestart: false };
294|     }
295|   }
296| 
297|   console.error(`${colorize("⚠", dim(""))} Reached max rounds (${config.maxRounds})`);
298|   return { messages: msgs, needsRestart: false };
299| }
