  5| // ─── Shared API Helpers ────────────────────────────────
  6| 
  7| function buildApiHeaders(config: AgentConfig): Record<string, string> {
  8|   const headers: Record<string, string> = { "Content-Type": "application/json" };
  9|   if (config.apiKey) headers["Authorization"] = `Bearer ${config.apiKey}`;
 10|   return headers;
 11| }
 12| 
 13| function parseUsage(data: Record<string, unknown>): UsageInfo | undefined {
 14|   const u = data.usage as Record<string, number> | undefined;
 15|   if (!u) return undefined;
 16|   return {
 17|     promptTokens: u.prompt_tokens,
 18|     completionTokens: u.completion_tokens,
 19|     totalTokens: u.total_tokens,
 20|   };
 21| }
 22| 
 23| async function retryDelay(attempt: number, maxRetries: number): Promise<void> {
 24|   const delay = 1000 * (attempt + 1);
 25|   console.error(`${colorize("⚠", dim(""))} Retrying in ${delay}ms...`);
 26|   await new Promise((r) => setTimeout(r, delay));
 27| }
 28| 
 29| async function handleRateLimit(response: Response, attempt: number, maxRetries: number): Promise<boolean> {
 30|   if (response.status === 429 && attempt < maxRetries - 1) {
 31|     await new Promise((r) => setTimeout(r, 2000 * (attempt + 1)));
 32|     return true; // retry
 33|   }
 34|   return false;
 35| }
