 37| // ─── Non-Streaming Completion ─────────────────────────
 38| 
 39| export interface CompletionResult {
 40|   message: ChatMessage;
 41|   usage?: UsageInfo;
 42| }
 43| 
 44| export async function chatCompletion(
 45|   messages: ChatMessage[],
 46|   tools: ToolDef[],
 47|   config: AgentConfig,
 48| ): Promise<CompletionResult> {
 49|   const url = `${config.apiBase}/chat/completions`;
 50|   const body = buildRequestBody(messages, tools, config);
 51|   const headers = buildApiHeaders(config);
 52|   const maxRetries = config.maxRetries;
 53| 
 54|   for (let attempt = 0; attempt < maxRetries; attempt++) {
 55|     try {
 56|       const response = await fetch(url, {
 57|         method: "POST",
 58|         headers,
 59|         body: JSON.stringify(body),
 60|       });
 61| 
 62|       if (!response.ok) {
 63|         const text = await response.text();
 64|         if (await handleRateLimit(response, attempt, maxRetries)) continue;
 65|         throw new Error(`API ${response.status}: ${text.substring(0, 500)}`);
 66|       }
 67| 
 68|       const data = await response.json();
 69|       const message = data.choices[0].message as ChatMessage;
 70|       return { message, usage: parseUsage(data) };
 71|     } catch (e) {
 72|       if (attempt === maxRetries - 1) throw e;
 73|       await retryDelay(attempt, maxRetries);
 74|     }
 75|   }
 76|   throw new Error("Unreachable");
 77| }
