 79| // ─── Streaming Completion ─────────────────────────────
 80| 
 81| export interface StreamEvent {
 82|   type: "content" | "tool_call_start" | "tool_call_delta" | "done" | "error";
 83|   content?: string;
 84|   toolIndex?: number;
 85|   toolId?: string;
 86|   toolName?: string;
 87|   toolArgs?: string;
 88|   finishReason?: string;
 89|   usage?: UsageInfo;
 90|   error?: string;
 91| }
 92| 
 93| export async function* chatCompletionStream(
 94|   messages: ChatMessage[],
 95|   tools: ToolDef[],
 96|   config: AgentConfig,
 97| ): AsyncGenerator<StreamEvent> {
 98|   const url = `${config.apiBase}/chat/completions`;
 99|   const body = {
100|     ...buildRequestBody(messages, tools, config),
101|     stream: true,
102|     stream_options: { include_usage: true },
103|   };
104|   const headers = buildApiHeaders(config);
105|   const maxRetries = config.maxRetries;
106| 
107|   for (let attempt = 0; attempt < maxRetries; attempt++) {
108|     try {
109|       const response = await fetch(url, {
110|         method: "POST",
111|         headers,
112|         body: JSON.stringify(body),
113|       });
114| 
115|       if (!response.ok) {
116|         const text = await response.text();
117|         if (await handleRateLimit(response, attempt, maxRetries)) continue;
118|         yield { type: "error", error: `API ${response.status}: ${text.substring(0, 500)}` };
119|         return;
120|       }
121| 
122|       const reader = response.body?.getReader();
123|       if (!reader) {
124|         yield { type: "error", error: "No response body reader" };
125|         return;
126|       }
127| 
128|       const decoder = new TextDecoder();
129|       let buffer = "";
130| 
131|       // Track accumulated tool calls
132|       const toolCalls: Array<{
133|         id: string;
134|         name: string;
135|         arguments: string;
136|       }> = [];
137|       let finishReason: string | null = null;
138|       let finalUsage: UsageInfo | undefined;
139| 
140|       try {
141|         while (true) {
142|           const { done, value } = await reader.read();
143|           if (done) break;
144| 
145|           buffer += decoder.decode(value, { stream: true });
146|           const lines = buffer.split("\n");
147|           buffer = lines.pop() || "";
148| 
149|           for (const line of lines) {
150|             const trimmed = line.trim();
151|             if (!trimmed || trimmed === "data: [DONE]") continue;
152|             if (!trimmed.startsWith("data: ")) continue;
153| 
154|             try {
155|               const json = JSON.parse(trimmed.substring(6));
156|               const choice = json.choices?.[0];
157|               if (!choice) {
158|                 // Final chunk with usage
159|                 if (json.usage) {
160|                   finalUsage = parseUsage(json);
161|                 }
162|                 continue;
163|               }
164| 
165|               const delta = choice.delta;
166|               if (!delta) continue;
167| 
168|               // Content delta
169|               if (delta.content) {
170|                 yield { type: "content", content: delta.content };
171|               }
172| 
173|               // Tool call deltas
174|               if (delta.tool_calls) {
175|                 for (const tc of delta.tool_calls) {
176|                   const idx = tc.index ?? 0;
177| 
178|                   // Initialize tool call if needed
179|                   while (toolCalls.length <= idx) {
180|                     toolCalls.push({ id: "", name: "", arguments: "" });
181|                   }
182| 
183|                   if (tc.id) {
184|                     toolCalls[idx].id = tc.id;
185|                     yield {
186|                       type: "tool_call_start",
187|                       toolIndex: idx,
188|                       toolId: tc.id,
189|                       toolName: tc.function?.name,
190|                     };
191|                   }
192|                   if (tc.function?.name) {
193|                     toolCalls[idx].name = tc.function.name;
194|                   }
195|                   if (tc.function?.arguments) {
196|                     toolCalls[idx].arguments += tc.function.arguments;
197|                     yield {
198|                       type: "tool_call_delta",
199|                       toolIndex: idx,
200|                       toolArgs: tc.function.arguments,
201|                     };
202|                   }
203|                 }
204|               }
205| 
206|               finishReason = choice.finish_reason ?? finishReason;
207|             } catch {
208|               // Skip malformed JSON lines
209|             }
210|           }
211|         }
212|       } finally {
213|         reader.releaseLock();
214|       }
215| 
216|       // Build final message
217|       const finalMessage: ChatMessage = {
218|         role: "assistant",
219|         content: null,
220|       };
221| 
222|       if (toolCalls.length > 0) {
223|         finalMessage.tool_calls = toolCalls.map((tc) => ({
224|           id: tc.id,
225|           type: "function" as const,
226|           function: {
227|             name: tc.name,
228|             arguments: tc.arguments,
229|           },
230|         }));
231|       }
232| 
233|       yield {
234|         type: "done",
235|         finishReason: finishReason ?? "stop",
236|         usage: finalUsage,
237|       };
238| 
239|       return;
240|     } catch (e) {
241|       if (attempt === maxRetries - 1) {
242|         yield { type: "error", error: (e as Error).message };
243|         return;
244|       }
245|       await retryDelay(attempt, maxRetries);
246|     }
247|   }
248| }
