250| // ─── Build Request Body ───────────────────────────────
251| 
252| function buildRequestBody(
253|   messages: ChatMessage[],
254|   tools: ToolDef[],
255|   config: AgentConfig,
256| ): Record<string, unknown> {
257|   const body: Record<string, unknown> = {
258|     model: config.model,
259|     messages,
260|     max_tokens: config.maxTokens,
261|     temperature: config.temperature,
262|     tools,
263|   };
264| 
265|   if (config.topP !== undefined) {
266|     body.top_p = config.topP;
267|   }
268| 
269|   if (config.stop) {
270|     const stops = config.stop.split(",").map((s) => s.trim()).filter(Boolean);
271|     if (stops.length === 1) {
272|       body.stop = stops[0];
273|     } else if (stops.length > 1) {
274|       body.stop = stops;
275|     }
276|   }
277| 
278|   if (config.responseFormat === "json") {
279|     body.response_format = { type: "json_object" };
280|   }
281| 
282|   if (config.logprobs) {
283|     body.logprobs = true;
284|     if (config.topLogprobs !== undefined) {
285|       body.top_logprobs = config.topLogprobs;
286|     }
287|   }
288| 
289|   if (config.userId) {
290|     body.user_id = config.userId;
291|   }
292| 
293|   if (config.thinking) {
294|     body.thinking = { type: "enabled" };
295|   }
296| 
297|   if (config.reasoningEffort) {
298|     body.reasoning_effort = config.reasoningEffort;
299|   }
300| 
301|   return body;
302| }
