304| // ─── Token Estimation ──────────────────────────────────
305| 
306| /**
307|  * Rough token estimation: ~4 characters per token.
308|  * This is a conservative estimate; actual tokens vary by model.
309|  * Claude: ~3.5 chars/token, GPT-4: ~4 chars/token, DeepSeek: ~3 chars/token.
310|  */
311| export function estimateTokens(text: string): number {
312|   return Math.ceil(text.length / 3.5);
313| }
314| 
315| export function estimateMessagesTokens(messages: ChatMessage[]): number {
316|   let total = 0;
317|   for (const msg of messages) {
318|     total += estimateTokens(msg.content ?? "");
319|     if (msg.tool_calls) {
320|       for (const tc of msg.tool_calls) {
321|         total += estimateTokens(tc.function.name);
322|         total += estimateTokens(tc.function.arguments);
323|       }
324|     }
325|     // Role and structure overhead
326|     total += 4;
327|   }
328|   return total;
329| }
