  3| // ─── Path Safety ───────────────────────────────────────
  4| 
  5| /**
  6|  * Check if a file path is safe to access.
  7|  * In sandbox mode, restricts access to the project directory.
  8|  * Always blocks access to sensitive system paths.
  9|  */
 10| export function isPathSafe(path: string, cwd: string, sandbox: boolean): SafetyCheck {
 11|   // Resolve to absolute path
 12|   let resolved: string;
 13|   try {
 14|     // Handle relative paths
 15|     if (path.startsWith("/")) {
 16|       resolved = path;
 17|     } else {
 18|       resolved = `${cwd}/${path}`;
 19|     }
 20|     // Normalize: resolve .. and .
 21|     const parts = resolved.split("/");
 22|     const normalized: string[] = [];
 23|     for (const part of parts) {
 24|       if (part === "..") {
 25|         if (normalized.length > 0) normalized.pop();
 26|       } else if (part !== "." && part !== "") {
 27|         normalized.push(part);
 28|       }
 29|     }
 30|     resolved = "/" + normalized.join("/");
 31|   } catch {
 32|     return { safe: false, reason: "Unable to resolve path" };
 33|   }
 34| 
 35|   // Block sensitive paths regardless of sandbox mode
 36|   const blockedPrefixes = [
 37|     "/etc/", "/dev/", "/proc/", "/sys/", "/boot/",
 38|     "/root/", "/var/log/", "/var/run/",
 39|     "/Library/", "/System/", "/private/etc/", "/private/var/",
 40|     "C:\\Windows", "C:\\Program Files",
 41|   ];
 42| 
 43|   // Block sensitive files exactly
 44|   const blockedExact = [
 45|     "/etc/passwd", "/etc/shadow", "/etc/hosts", "/etc/ssl",
 46|     "/etc/ssh", "/etc/sudoers",
 47|   ];
 48| 
 49|   for (const prefix of blockedPrefixes) {
 50|     if (resolved.startsWith(prefix)) {
 51|       return { safe: false, reason: `Path is in blocked system directory: ${prefix}` };
 52|     }
 53|   }
 54|   for (const exact of blockedExact) {
 55|     if (resolved === exact || resolved.startsWith(exact + "/")) {
 56|       return { safe: false, reason: `Path is a sensitive system file: ${exact}` };
 57|     }
 58|   }
 59| 
 60|   // Block hidden files in home directory
 61|   const home = Deno.env.get("HOME") ?? "/home";
 62|   if (resolved.startsWith(home + "/.") && !resolved.includes(home + "/.config")) {
 63|     // Allow .config but block .ssh, .gnupg, etc.
 64|     const relHome = resolved.substring(home.length);
 65|     if (relHome.match(/^\/\.(ssh|gnupg|aws|docker|kube|gcloud|azure)/)) {
 66|       return { safe: false, reason: `Path is in sensitive hidden directory` };
 67|     }
 68|   }
 69| 
 70|   // Sandbox: restrict to project directory
 71|   if (sandbox) {
 72|     const normalizedCwd = cwd.endsWith("/") ? cwd.substring(0, cwd.length - 1) : cwd;
 73|     if (!resolved.startsWith(normalizedCwd + "/") && resolved !== normalizedCwd) {
 74|       return {
 75|         safe: false,
 76|         reason: `Path outside project directory. Sandbox restricts to: ${normalizedCwd}`,
 77|       };
 78|     }
 79|   }
 80| 
 81|   return { safe: true };
 82| }
