 84| // ─── Command Safety ───────────────────────────────────
 85| 
 86| const DANGEROUS_PATTERNS: Array<{ pattern: RegExp; reason: string }> = [
 87|   { pattern: /\brm\s+-rf\b/, reason: "Recursive force delete (rm -rf)" },
 88|   { pattern: /\brm\s+-r\b/, reason: "Recursive delete (rm -r)" },
 89|   { pattern: /\bsudo\b/, reason: "Superuser execution (sudo)" },
 90|   { pattern: /\bchmod\s+777\b/, reason: "World-writable permissions (chmod 777)" },
 91|   { pattern: /\bchmod\s+-R\b/, reason: "Recursive permission change" },
 92|   { pattern: /\bchown\b/, reason: "Ownership change (chown)" },
 93|   { pattern: /\bmkfs\./, reason: "Filesystem format (mkfs)" },
 94|   { pattern: /\bdd\s+if=/, reason: "Disk duplication (dd)" },
 95|   { pattern: /\b>:.*\/dev\//, reason: "Writing to device files" },
 96|   { pattern: /\bcurl.*\|\s*(ba)?sh\b/, reason: "Piping curl to shell" },
 97|   { pattern: /\bwget.*\|\s*(ba)?sh\b/, reason: "Piping wget to shell" },
 98|   { pattern: /\bgit\s+push\s+--force/, reason: "Force push to remote" },
 99|   { pattern: /\bgit\s+push\s+-f\b/, reason: "Force push to remote" },
100|   { pattern: /\bdocker\s+rm\b/, reason: "Docker container/image removal" },
101|   { pattern: /\bdocker\s+system\s+prune\b/, reason: "Docker system prune" },
102|   { pattern: /\bshutdown\b/, reason: "System shutdown" },
103|   { pattern: /\breboot\b/, reason: "System reboot" },
104|   { pattern: /\bkill\s+-9\b/, reason: "Force kill process (kill -9)" },
105|   { pattern: /\bpkill\b/, reason: "Process kill by name (pkill)" },
106|   { pattern: /:\(\)\s*\{\s*:\s*\|:.*\};:/, reason: "Fork bomb detected" },
107| ];
108| 
109| export function isCommandSafe(command: string): SafetyCheck {
110|   const trimmed = command.trim();
111| 
112|   // Block empty commands
113|   if (!trimmed) {
114|     return { safe: false, reason: "Empty command" };
115|   }
116| 
117|   // Check each dangerous pattern
118|   for (const { pattern, reason } of DANGEROUS_PATTERNS) {
119|     if (pattern.test(trimmed)) {
120|       return { safe: false, reason };
121|     }
122|   }
123| 
124|   // Block commands that try to modify files in home directory
125|   if (trimmed.includes("$HOME") || trimmed.includes("~")) {
126|     if (/\brm\b|\bmv\b|\bcp\b.*[\$HOME~]/.test(trimmed)) {
127|       return { safe: false, reason: "Modifying files in \$HOME" };
128|     }
129|   }
130| 
131|   return { safe: true };
132| }
