136| export function sandboxContext(cwd: string, sandbox: boolean): string {
137|   if (!sandbox) return "";
138|   return `\n\nSafety: Path sandbox is active. All file access is restricted to: ${cwd}. Sensitive system paths are blocked. Dangerous commands are detected and warned about.`;
139| }
