201| function requireNumber(val: unknown, name: string, min?: number, max?: number): string | null {
202|   if (typeof val !== "number" || isNaN(val)) return `Error: ${name} must be a number`;
203|   if (min !== undefined && val < min) return `Error: ${name} must be >= ${min}`;
204|   if (max !== undefined && val > max) return `Error: ${name} must be <= ${max}`;
205|   return null;
