210| async function execReadFile(path: string, opts: ToolExecOptions): Promise<ToolExecResult> {
211|   const err = requireString(path, "path");
212|   if (err) return { output: err, error: true };
213|   const safety = isPathSafe(path, opts.cwd, opts.sandbox);
214|   if (!safety.safe) return { output: `Error: ${safety.reason}`, error: true };
215|   if (opts.dryRun) return { output: `[dry-run] Would read file: ${path}`, error: false };
216| 
217|   try {
218|     const content = await Deno.readTextFile(path);
219|     const lines = content.split("\n");
220|     const numbered = lines.map((line, i) => `${String(i + 1).padStart(4, " ")}| ${line}`);
221|     return { output: numbered.join("\n"), error: false };
222|   } catch (e) {
223|     return { output: `Error reading file: ${(e as Error).message}`, error: true };
224|   }
225| }
