227| async function execWriteFile(path: string, content: string, opts: ToolExecOptions): Promise<ToolExecResult> {
228|   const pathErr = requireString(path, "path");
229|   if (pathErr) return { output: pathErr, error: true };
230|   if (content === undefined || content === null || typeof content !== "string") return { output: "Error: content is required and must be a string", error: true };
231| 
232|   const safety = isPathSafe(path, opts.cwd, opts.sandbox);
233|   if (!safety.safe) return { output: `Error: ${safety.reason}`, error: true };
234| 
235|   if (opts.approve) {
236|     const preview = content.length > 200 ? content.substring(0, 200) + "..." : content;
237|     console.error(`\n${colorize("✏️", C.yellow)} ${bold("write_file")} to ${colorize(path, C.white)}`);
238|     console.error(dim(`   Preview: ${preview}`));
239|     const { promptYesNo } = await import("./ca_ui.ts");
240|     if (!await promptYesNo(`Write ${content.length} bytes to ${path}?`)) {
241|       return { output: `User declined write to ${path}`, error: false };
242|     }
243|   }
244| 
245|   if (opts.dryRun) return { output: `[dry-run] Would write ${content.length} bytes to: ${path}`, error: false };
246| 
247|   // Read old content for diff before writing
248|   let oldContent: string | null = null;
249|   try { oldContent = await Deno.readTextFile(path); } catch { /* new file */ }
250| 
251|   // Git auto-snapshot
252|   if (opts.autoCommit && oldContent !== null) {
253|     const hash = await gitSnapshot(path, opts.cwd);
254|     if (hash) console.error(`  ${colorize("📸", C.dim)} ${dim(`git snapshot: ${hash}`)}`);
255|   }
256| 
257|   try {
258|     const lastSep = path.lastIndexOf("/");
259|     if (lastSep > 0) await Deno.mkdir(path.substring(0, lastSep), { recursive: true });
260|     await Deno.writeTextFile(path, content);
261| 
262|     // Show colored diff
263|     const diff = await computeDiff(path, oldContent, content, opts.cwd);
264|     if (diff) console.error(diff);
265| 
266|     const existed = oldContent !== null;
267|     return {
268|       output: existed
269|         ? `Successfully overwrote ${path} with ${content.length} bytes`
270|         : `Successfully created ${path} with ${content.length} bytes`,
271|       error: false,
272|       diff: diff || undefined,
273|     };
274|   } catch (e) {
275|     return { output: `Error writing file: ${(e as Error).message}`, error: true };
276|   }
277| }
