279| async function execRunCommand(command: string, workdir: string | undefined, opts: ToolExecOptions): Promise<ToolExecResult> {
280|   const err = requireString(command, "command");
281|   if (err) return { output: err, error: true };
282| 
283|   const safety = isCommandSafe(command);
284|   if (!safety.safe) {
285|     if (opts.approve) {
286|       const { promptYesNo } = await import("./ca_ui.ts");
287|       console.error(`\n${colorize("⚠", C.yellow)} ${bold("Potentially dangerous command:")} ${dim(safety.reason ?? "Unknown")}`);
288|       console.error(`   ${dim(command)}`);
289|       if (!await promptYesNo("Execute anyway?")) return { output: `User declined to run: ${command}`, error: false };
290|     } else {
291|       return { output: `Error: Command blocked: ${safety.reason}. Use --approve to override.`, error: true };
292|     }
293|   }
294| 
295|   const cwd = workdir ?? opts.cwd;
296|   if (workdir) {
297|     const dirSafety = isPathSafe(workdir, opts.cwd, opts.sandbox);
298|     if (!dirSafety.safe) return { output: `Error: Working directory: ${dirSafety.reason}`, error: true };
299|   }
300| 
301|   if (opts.dryRun) return { output: `[dry-run] Would run: ${command} (in ${cwd})`, error: false };
302| 
303|   try {
304|     const cmd = new Deno.Command("bash", { args: ["-c", command], cwd, stdout: "piped", stderr: "piped", env: Deno.env.toObject() });
305|     const proc = cmd.spawn();
306| 
307|     // Enforce 120s timeout
308|     const timeoutMs = 120_000;
309|     const timeout = setTimeout(async () => {
310|       try { proc.kill("SIGTERM"); } catch { /* already dead */ }
311|     }, timeoutMs);
312| 
313|     let output: Deno.CommandOutput;
314|     try {
315|       output = await proc.output();
316|     } finally {
317|       clearTimeout(timeout);
318|     }
319| 
320|     const { code, stdout, stderr } = output;
321|     const out = new TextDecoder().decode(stdout);
322|     const err = new TextDecoder().decode(stderr);
323|     let result = "";
324|     if (out) result += out;
325|     if (err) result += (result ? "\n" : "") + err;
326|     if (code === null) {
327|       result += `\n[timeout after ${timeoutMs / 1000}s]`;
328|     } else {
329|       result += `\n[exit: ${code}]`;
330|     }
331|     if (result.length > 10000) result = result.substring(0, 10000) + "\n...[truncated]";
332|     return { output: result, error: code !== 0 };
333|   } catch (e) {
334|     return { output: `Error running command: ${(e as Error).message}`, error: true };
335|   }
336| }
