338| async function execSearchFiles(pattern: string, path: string | undefined, glob: string | undefined, maxResults: number, opts: ToolExecOptions): Promise<ToolExecResult> {
339|   const err = requireString(pattern, "pattern");
340|   if (err) return { output: err, error: true };
341|   const searchPath = path ?? opts.cwd;
342|   const safety = isPathSafe(searchPath, opts.cwd, opts.sandbox);
343|   if (!safety.safe) return { output: `Error: ${safety.reason}`, error: true };
344|   if (opts.dryRun) return { output: `[dry-run] Would search for "${pattern}" in ${searchPath}`, error: false };
345| 
346|   try {
347|     const args = ["--line-number", "--no-heading", "--color=never", "-e", pattern];
348|     if (glob) args.push("--glob", glob);
349|     args.push(searchPath);
350|     for (const d of ["!.git", "!node_modules", "!dist", "!target", "!.svn"]) args.push("--glob", d);
351|     args.push("-m", String(maxResults));
352| 
353|     let result: string;
354|     try {
355|       const cmd = new Deno.Command("rg", { args, stdout: "piped", stderr: "piped" });
356|       const { code, stdout } = await cmd.output();
357|       if (code === 0 || code === 1) { result = new TextDecoder().decode(stdout); }
358|       else throw new Error("rg failed");
359|     } catch {
360|       // Fallback to grep — translate glob to --include patterns
361|       const grepArgs = ["-rn", "-e", pattern];
362|       if (glob) {
363|         const patterns = glob.split(",").map((g) => g.trim());
364|         for (const p of patterns) {
365|           grepArgs.push("--include=" + p);
366|         }
367|       }
368|       grepArgs.push(searchPath);
369|       const cmd = new Deno.Command("grep", { args: grepArgs, stdout: "piped", stderr: "piped" });
370|       const { stdout } = await cmd.output();
371|       result = new TextDecoder().decode(stdout);
372|     }
373| 
374|     if (!result || !result.trim()) return { output: `No results found for pattern: ${pattern}`, error: false };
375|     const lines = result.trim().split("\n");
376|     if (lines.length >= maxResults) {
377|       return { output: lines.slice(0, maxResults).join("\n") + `\n... (${lines.length - maxResults} more results not shown)`, error: false };
378|     }
379|     return { output: result.trim(), error: false };
380|   } catch (e) {
381|     return { output: `Error searching files: ${(e as Error).message}`, error: true };
382|   }
383| }
