388|   if (!safety.safe) return { output: `Error: ${safety.reason}`, error: true };
389|   const d = Math.max(1, Math.min(depth, 5));
390|   if (opts.dryRun) return { output: `[dry-run] Would list directory: ${dirPath} (depth: ${d})`, error: false };
391| 
392|   try {
393|     const lines: string[] = [];
394|     await listDirRecursive(dirPath, d, 0, lines, opts.cwd);
395|     return { output: lines.join("\n") || "(empty directory)", error: false };
396|   } catch (e) {
