401| async function listDirRecursive(dirPath: string, maxDepth: number, currentDepth: number, lines: string[], cwd: string): Promise<void> {
402|   if (currentDepth >= maxDepth) return;
403|   const entries: Deno.DirEntry[] = [];
404|   for await (const entry of Deno.readDir(dirPath)) entries.push(entry);
405|   entries.sort((a, b) => a.isDirectory !== b.isDirectory ? (a.isDirectory ? -1 : 1) : a.name.localeCompare(b.name));
406| 
407|   const indent = "  ".repeat(currentDepth);
408|   const prefix = currentDepth === 0 ? (dirPath === cwd ? "./" : dirPath + "/") : "";
409|   if (currentDepth === 0) lines.push(`${prefix}`);
410| 
411|   for (const entry of entries) {
412|     if (entry.name.startsWith(".") && entry.name !== ".ca.json") continue;
413|     const icon = entry.isDirectory ? "📁" : "📄";
414|     const sizeStr = entry.isFile ? await formatSize(`${dirPath}/${entry.name}`) : "";
415|     lines.push(`${indent}  ${icon} ${entry.name}${sizeStr ? " " + dim(sizeStr) : ""}`);
416|     if (entry.isDirectory && currentDepth + 1 < maxDepth) {
417|       await listDirRecursive(`${dirPath}/${entry.name}`, maxDepth, currentDepth + 1, lines, cwd);
418|     }
419|   }
420| }
