441| async function execApplyDiff(path: string, search: string, replace: string, opts: ToolExecOptions): Promise<ToolExecResult> {
442|   const pathErr = requireString(path, "path");
443|   if (pathErr) return { output: pathErr, error: true };
444|   const searchErr = requireString(search, "search");
445|   if (searchErr) return { output: searchErr, error: true };
446|   const safety = isPathSafe(path, opts.cwd, opts.sandbox);
447|   if (!safety.safe) return { output: `Error: ${safety.reason}`, error: true };
448|   if (opts.dryRun) return { output: `[dry-run] Would apply diff to ${path}: replace ${search.length} chars with ${replace.length} chars`, error: false };
449| 
450|   try {
451|     const original = await Deno.readTextFile(path);
452|     const escaped = search.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
453|     const count = (original.match(new RegExp(escaped, "g")) || []).length;
454| 
455|     if (count === 0) return { output: `Error: Could not find the search block in ${path}. Match exact whitespace.`, error: true };
456|     if (count > 1) return { output: `Error: Search block found ${count} times in ${path}. Must match exactly once. Make the search more specific.`, error: true };
457| 
458|     const updated = original.split(search).join(replace);
459| 
460|     if (opts.approve) {
461|       const { promptYesNo } = await import("./ca_ui.ts");
462|       const sp = search.length > 120 ? search.substring(0, 120) + "..." : search;
463|       const rp = replace.length > 120 ? replace.substring(0, 120) + "..." : replace;
464|       console.error(`\n${colorize("📝", C.yellow)} ${bold("apply_diff")} to ${colorize(path, C.white)}`);
465|       console.error(dim(`   - ${sp}`));
466|       console.error(dim(`   + ${rp}`));
467|       if (!await promptYesNo("Apply this change?")) return { output: `User declined diff to ${path}`, error: false };
468|     }
469| 
470|     // Git auto-snapshot
471|     if (opts.autoCommit) {
472|       const hash = await gitSnapshot(path, opts.cwd);
473|       if (hash) console.error(`  ${colorize("📸", C.dim)} ${dim(`git snapshot: ${hash}`)}`);
474|     }
475| 
476|     await Deno.writeTextFile(path, updated);
477| 
478|     // Show colored diff
479|     const diff = await computeDiff(path, original, updated, opts.cwd);
480|     if (diff) console.error(diff);
481| 
482|     return { output: `Successfully applied diff to ${path}: replaced ${search.length} bytes with ${replace.length} bytes`, error: false, diff: diff || undefined };
483|   } catch (e) {
484|     return { output: `Error applying diff: ${(e as Error).message}`, error: true };
485|   }
486| }
