488| // ─── Git Auto-Snapshot ─────────────────────────────────
489| 
490| async function gitSnapshot(filePath: string, cwd: string): Promise<string | null> {
491|   try {
492|     const revParse = new Deno.Command("git", { args: ["rev-parse", "--show-toplevel"], cwd, stdout: "piped", stderr: "piped" });
493|     const { code: revCode } = await revParse.output();
494|     if (revCode !== 0) return null;
495| 
496|     const add = new Deno.Command("git", { args: ["add", filePath], cwd, stdout: "piped", stderr: "piped" });
497|     const { code: addCode } = await add.output();
498|     if (addCode !== 0) return null;
499| 
500|     const msg = `snapshot: auto-commit ${filePath} before CA modification`;
501|     const commit = new Deno.Command("git", { args: ["commit", "-m", msg, "--no-verify"], cwd, stdout: "piped", stderr: "piped" });
502|     const { code: commitCode, stdout: commitOut } = await commit.output();
503|     if (commitCode === 0) {
504|       const text = new TextDecoder().decode(commitOut).trim();
505|       const match = text.match(/\[.*?([a-f0-9]{7}).*?\]/);
506|       return match ? match[1] : null;
507|     }
508|     return null;
509|   } catch { return null; }
510| }
