512| // ─── Colored Diff Display ──────────────────────────────
513| 
514| async function computeDiff(filePath: string, oldContent: string | null, newContent: string, cwd: string): Promise<string> {
515|   if (oldContent === null) {
516|     // New file — show all lines as additions
517|     const lines = newContent.split("\n").slice(0, 20);
518|     const preview = lines.map((l) => `${C.green}+ ${l}${C.reset}`).join("\n");
519|     const suffix = newContent.split("\n").length > 20 ? `\n${C.dim}  ... (+${newContent.split("\n").length - 20} more lines)${C.reset}` : "";
520|     return `\n${C.dim}  --- new file: ${filePath}${C.reset}\n${preview}${suffix}`;
521|   }
522| 
523|   // Try git diff
524|   try {
525|     const tmpDir = Deno.env.get("TMPDIR") ?? "/tmp";
526|     const oldFile = `${tmpDir}/.ca_diff_old_${Date.now()}`;
527|     const newFile = `${tmpDir}/.ca_diff_new_${Date.now()}`;
528|     await Deno.writeTextFile(oldFile, oldContent);
529|     await Deno.writeTextFile(newFile, newContent);
530| 
531|     const diff = new Deno.Command("git", {
532|       args: ["diff", "--no-index", "--color=always", "--unified=3", oldFile, newFile],
533|       stdout: "piped", stderr: "piped",
534|     });
535|     const { stdout } = await diff.output();
536|     const diffText = new TextDecoder().decode(stdout);
537| 
538|     try { await Deno.remove(oldFile); } catch { /* ok */ }
539|     try { await Deno.remove(newFile); } catch { /* ok */ }
540| 
541|     if (diffText.trim()) {
542|       const lines = diffText.split("\n");
543|       // Keep only hunk headers and changed/context lines, strip file headers
544|       const filtered = lines.filter((l) =>
545|         l.startsWith("@@") || l.startsWith("+") || l.startsWith("-") || l.startsWith(" ")
546|       );
547|       // Limit to 30 lines
548|       if (filtered.length > 30) {
549|         return `\n${filtered.slice(0, 30).join("\n")}\n${dim(`  ... (${filtered.length - 30} more lines)`)}`;
550|       }
551|       return `\n${filtered.join("\n")}`;
552|     }
553|   } catch { /* fall through */ }
554| 
555|   // Fallback: simple diff
556|   return simpleDiff(oldContent, newContent);
557| }
558| 
559| function simpleDiff(oldText: string, newText: string): string {
560|   const oldLines = oldText.split("\n");
561|   const newLines = newText.split("\n");
562|   const result: string[] = [];
563|   const maxLen = Math.max(oldLines.length, newLines.length);
564|   let oldIdx = 0, newIdx = 0;
565|   let shown = 0;
566|   const MAX_SHOWN = 30;
567| 
568|   while ((oldIdx < oldLines.length || newIdx < newLines.length) && shown < MAX_SHOWN) {
569|     const oldLine = oldIdx < oldLines.length ? oldLines[oldIdx] : null;
570|     const newLine = newIdx < newLines.length ? newLines[newIdx] : null;
571| 
572|     if (oldLine === newLine) {
573|       if (shown < 6 || (oldIdx > oldLines.length - 6 && newIdx > newLines.length - 6)) {
574|         result.push(`  ${oldLine}`);
575|         shown++;
576|       } else if (result.length > 0 && result[result.length - 1] !== "...") {
577|         result.push(dim("  ..."));
578|         shown++;
579|       }
580|       oldIdx++; newIdx++;
581|     } else {
582|       let syncFound = false;
583|       for (let ahead = 1; ahead < 5 && (oldIdx + ahead < oldLines.length || newIdx + ahead < newLines.length); ahead++) {
584|         if (oldIdx + ahead < oldLines.length && newIdx < newLines.length && oldLines[oldIdx + ahead] === newLines[newIdx]) {
585|           for (let k = 0; k < ahead && shown < MAX_SHOWN; k++, shown++) {
586|             result.push(`${C.red}- ${oldLines[oldIdx + k]}${C.reset}`);
587|           }
588|           oldIdx += ahead;
589|           syncFound = true;
590|           break;
591|         }
592|         if (newIdx + ahead < newLines.length && oldIdx < oldLines.length && newLines[newIdx + ahead] === oldLines[oldIdx]) {
593|           for (let k = 0; k < ahead && shown < MAX_SHOWN; k++, shown++) {
594|             result.push(`${C.green}+ ${newLines[newIdx + k]}${C.reset}`);
595|           }
596|           newIdx += ahead;
597|           syncFound = true;
598|           break;
599|         }
600|       }
601|       if (!syncFound) {
602|         if (oldLine !== null) { result.push(`${C.red}- ${oldLine}${C.reset}`); shown++; }
603|         if (newLine !== null) { result.push(`${C.green}+ ${newLine}${C.reset}`); shown++; }
604|         oldIdx++; newIdx++;
605|       }
606|     }
607|   }
608| 
609|   const remaining = (oldLines.length - oldIdx) + (newLines.length - newIdx);
610|   if (remaining > 0) result.push(dim(`  ... (${remaining} more changes)`));
611|   return `\n${result.join("\n")}`;
612| }
