 46| // ─── Spinner ───────────────────────────────────────────
 47| 
 48| const SPINNER_FRAMES = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
 49| 
 50| export class Spinner {
 51|   private interval: number | null = null;
 52|   private frame = 0;
 53|   private message = "";
 54|   private running = false;
 55| 
 56|   start(msg: string): void {
 57|     if (!Deno.stderr.isTerminal()) {
 58|       console.error(`[ca] ${msg}`);
 59|       return;
 60|     }
 61|     this.message = msg;
 62|     this.frame = 0;
 63|     this.running = true;
 64|     this.render();
 65|     this.interval = setInterval(() => {
 66|       this.frame = (this.frame + 1) % SPINNER_FRAMES.length;
 67|       this.render();
 68|     }, 80);
 69|   }
 70| 
 71|   private render(): void {
 72|     if (!this.running) return;
 73|     const spinner = SPINNER_FRAMES[this.frame];
 74|     Deno.stderr.writeSync(
 75|       new TextEncoder().encode(
 76|         `\r${colorize(spinner, C.cyan)} ${dim(this.message)}`,
 77|       ),
 78|     );
 79|   }
 80| 
 81|   stop(): void {
 82|     if (this.interval !== null) {
 83|       clearInterval(this.interval);
 84|       this.interval = null;
 85|     }
 86|     this.running = false;
 87|     if (Deno.stderr.isTerminal()) {
 88|       Deno.stderr.writeSync(new TextEncoder().encode("\r\x1b[K"));
 89|     }
 90|   }
 91| 
 92|   succeed(msg: string): void {
 93|     this.stop();
 94|     console.error(`${colorize("✔", C.green)} ${dim(msg)}`);
 95|   }
 96| 
 97|   fail(msg: string): void {
 98|     this.stop();
 99|     console.error(`${colorize("✘", C.red)} ${dim(msg)}`);
100|   }
101| 
102|   warn(msg: string): void {
103|     this.stop();
104|     console.error(`${colorize("⚠", C.yellow)} ${dim(msg)}`);
105|   }
106| 
107|   update(msg: string): void {
108|     this.message = msg;
109|     if (!this.running) return;
110|     if (Deno.stderr.isTerminal()) {
111|       const spinner = SPINNER_FRAMES[this.frame];
112|       Deno.stderr.writeSync(
113|         new TextEncoder().encode(
114|           `\r${colorize(spinner, C.cyan)} ${dim(msg)}`,
115|         ),
116|       );
117|     }
118|   }
119| }
