179| // ─── Syntax Highlighting (basic) ──────────────────────
180| 
181| export function highlightCode(code: string, lang?: string): string {
182|   // Strip existing ANSI codes for safety
183|   code = code.replace(/\x1b\[[0-9;]*m/g, "");
184| 
185|   const lines = code.split("\n");
186|   const result: string[] = [];
187|   let inBlock = false;
188|   let blockLang = "";
189| 
190|   for (const line of lines) {
191|     if (line.startsWith("```")) {
192|       if (!inBlock) {
193|         inBlock = true;
194|         blockLang = line.substring(3).trim();
195|         result.push(colorize(line, C.dim));
196|       } else {
197|         inBlock = false;
198|         result.push(colorize(line, C.dim));
199|       }
200|     } else if (inBlock) {
201|       // Basic syntax highlighting inside code blocks
202|       result.push(highlightCodeLine(line, blockLang));
203|     } else {
204|       result.push(line);
205|     }
206|   }
207|   return result.join("\n");
208| }
209| 
210| function highlightCodeLine(line: string, lang: string): string {
211|   // Keywords for common languages
212|   const keywords = new Set([
213|     "import", "export", "from", "const", "let", "var", "function",
214|     "return", "if", "else", "for", "while", "do", "switch", "case",
215|     "break", "continue", "class", "extends", "new", "this", "super",
216|     "try", "catch", "finally", "throw", "async", "await", "yield",
217|     "type", "interface", "enum", "implements", "private", "public",
218|     "protected", "static", "readonly", "abstract", "def", "fn", "pub",
219|     "mod", "use", "struct", "impl", "match", "where", "mut", "ref",
220|   ]);
221| 
222|   // String literals
223|   line = line.replace(
224|     /(["'`])(?:(?=(\\?))\2.)*?\1/g,
225|     (m) => colorize(m, C.green),
226|   );
227| 
228|   // Comments
229|   if (line.match(/^\s*\/\//)) {
230|     return colorize(line, C.dim + C.italic);
231|   }
232|   line = line.replace(
233|     /\/\/.*$/,
234|     (m) => colorize(m, C.dim + C.italic),
235|   );
236| 
237|   // Keywords (word boundaries)
238|   for (const kw of keywords) {
239|     const re = new RegExp(`\\b${kw}\\b`, "g");
240|     line = line.replace(re, colorize(kw, C.magenta));
241|   }
242| 
243|   // Numbers
244|   line = line.replace(
245|     /\b\d+\.?\d*\b/g,
246|     (m) => colorize(m, C.yellow),
247|   );
248| 
249|   return line;
250| }
