254| export async function promptYesNo(question: string): Promise<boolean> {
255|   const encoder = new TextEncoder();
256|   const decoder = new TextDecoder();
257|   await Deno.stderr.write(encoder.encode(`\n${colorize("?", C.yellow)} ${question} ${dim("[y/N]")} `));
258| 
259|   const buf = new Uint8Array(256);
260|   const n = await Deno.stdin.read(buf);
261|   if (n === null) return false;
262| 
263|   const answer = decoder.decode(buf.subarray(0, n)).trim().toLowerCase();
264|   return answer === "y" || answer === "yes";
265| }
