  75|     const branch = new TextDecoder().decode(branchOut).trim();
  76|     if (branch) parts.push(`Git branch: ${branch}`);
  77| 
  78|     const gitStatus = new Deno.Command("git", {
  79|       args: ["status", "--short"],
  80|       cwd,
  81|       stdout: "piped",
  82|       stderr: "piped",
  83|     });
  84|     const { stdout: statusOut } = await gitStatus.output();
  85|     const status = new TextDecoder().decode(statusOut).trim();
  86|     if (status) {
  87|       const changedFiles = status.split("\n").slice(0, 15);
  88|       parts.push(`Changed files:\n${changedFiles.join("\n")}`);
