  91| 
  92|   // Directory overview
  93|   try {
  94|     const entries: string[] = [];
  95|     for await (const entry of Deno.readDir(cwd)) {
  96|       if (entry.name.startsWith(".")) continue;
  97|       const icon = entry.isDirectory ? "/" : "";
  98|       entries.push(`  ${entry.name}${icon}`);
  99|     }
 100|     if (entries.length > 0 && entries.length <= 30) {
 101|       parts.push(`Top-level directory:\n${entries.sort().join("\n")}`);
 102|     }
 103|   } catch { /* can't read dir */ }
 104| 
 105|   // Language detection
 106|   try {
 107|     const exts = new Map<string, number>();
 108|     for await (const entry of Deno.readDir(cwd)) {
 109|       if (entry.isFile) {
 110|         const ext = entry.name.includes(".") ? entry.name.split(".").pop() ?? "" : "";
 111|         if (ext && ext.length < 10) {
 112|           exts.set(ext, (exts.get(ext) ?? 0) + 1);
 113|         }
 114|       }
 115|     }
 116|     if (exts.size > 0) {
 117|       const sorted = [...exts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6);
 118|       parts.push(`File types: ${sorted.map(([ext, count]) => `.${ext}(${count})`).join(", ")}`);
 119|     }
 120|   } catch { /* can't scan */ }
 121| 
 122|   return parts.join("\n");
 123| }
