 313| export function estimateMessagesTokens(messages: ChatMessage[]): number {
 314|   let total = 0;
 315|   for (const msg of messages) {
 316|     total += estimateTokens(msg.content ?? "");
 317|     if (msg.tool_calls) {
 318|       for (const tc of msg.tool_calls) {
 319|         total += estimateTokens(tc.function.name);
 320|         total += estimateTokens(tc.function.arguments);
 321|       }
 322|     }
 323|     // Role and structure overhead
 324|     total += 4;
 325|   }
 326|   return total;
 327| }
