 507|     if (diffText.trim()) {
 508|       const lines = diffText.split("\n");
 509|       // Keep only hunk headers and changed/context lines, strip file headers
 510|       const filtered = lines.filter((l) =>
 511|         l.startsWith("@@") || l.startsWith("+") || l.startsWith("-") || l.startsWith(" ")
 512|       );
 513|       // Limit to 30 lines
 514|       if (filtered.length > 30) {
 515|         return `\n${filtered.slice(0, 30).join("\n")}\n${dim(`  ... (${filtered.length - 30} more lines)`)}`;
 516|       }
 517|       return `\n${filtered.join("\n")}`;
 518|     }
 519|   } catch { /* fall through */ }
 520| 
 521|   // Fallback: simple diff
