 525| function simpleDiff(oldText: string, newText: string): string {
 526|   const oldLines = oldText.split("\n");
 527|   const newLines = newText.split("\n");
 528|   const result: string[] = [];
 529|   const maxLen = Math.max(oldLines.length, newLines.length);
 530|   let oldIdx = 0, newIdx = 0;
 531|   let shown = 0;
 532|   const MAX_SHOWN = 30;
 533| 
 534|   while ((oldIdx < oldLines.length || newIdx < newLines.length) && shown < MAX_SHOWN) {
 535|     const oldLine = oldIdx < oldLines.length ? oldLines[oldIdx] : null;
 536|     const newLine = newIdx < newLines.length ? newLines[newIdx] : null;
 537| 
 538|     if (oldLine === newLine) {
 539|       if (shown < 6 || (oldIdx > oldLines.length - 6 && newIdx > newLines.length - 6)) {
 540|         result.push(`  ${oldLine}`);
 541|         shown++;
 542|       } else if (result.length > 0 && result[result.length - 1] !== "...") {
 543|         result.push(dim("  ..."));
 544|         shown++;
 545|       }
 546|       oldIdx++; newIdx++;
 547|     } else {
 548|       let syncFound = false;
 549|       for (let ahead = 1; ahead < 5 && (oldIdx + ahead < oldLines.length || newIdx + ahead < newLines.length); ahead++) {
 550|         if (oldIdx + ahead < oldLines.length && newIdx < newLines.length && oldLines[oldIdx + ahead] === newLines[newIdx]) {
 551|           for (let k = 0; k < ahead && shown < MAX_SHOWN; k++, shown++) {
 552|             result.push(`${C.red}- ${oldLines[oldIdx + k]}${C.reset}`);
 553|           }
 554|           oldIdx += ahead;
 555|           syncFound = true;
 556|           break;
 557|         }
 558|         if (newIdx + ahead < newLines.length && oldIdx < oldLines.length && newLines[newIdx + ahead] === oldLines[oldIdx]) {
 559|           for (let k = 0; k < ahead && shown < MAX_SHOWN; k++, shown++) {
 560|             result.push(`${C.green}+ ${newLines[newIdx + k]}${C.reset}`);
 561|           }
 562|           newIdx += ahead;
 563|           syncFound = true;
 564|           break;
 565|         }
 566|       }
 567|       if (!syncFound) {
 568|         if (oldLine !== null) { result.push(`${C.red}- ${oldLine}${C.reset}`); shown++; }
 569|         if (newLine !== null) { result.push(`${C.green}+ ${newLine}${C.reset}`); shown++; }
 570|         oldIdx++; newIdx++;
 571|       }
 572|     }
 573|   }
 574| 
 575|   const remaining = (oldLines.length - oldIdx) + (newLines.length - newIdx);
 576|   if (remaining > 0) result.push(dim(`  ... (${remaining} more changes)`));
 577|   return `\n${result.join("\n")}`;
 578| }
