 109| export function isCommandSafe(command: string): SafetyCheck {
 110|   const trimmed = command.trim();
 111| 
 112|   // Block empty commands
 113|   if (!trimmed) {
 114|     return { safe: false, reason: "Empty command" };
 115|   }
 116| 
 117|   // Check each dangerous pattern
 118|   for (const { pattern, reason } of DANGEROUS_PATTERNS) {
 119|     if (pattern.test(trimmed)) {
 120|       return { safe: false, reason };
 121|     }
 122|   }
 123| 
 124|   // Block commands that try to escape the sandbox
 125|   if (trimmed.includes("$HOME") || trimmed.includes("$HOME")) {
 126|     // Allow if it's just reading, not modifying
 127|     if (/\brm\b|\bmv\b|\bcp\b.*\$HOME/.test(trimmed)) {
 128|       return { safe: false, reason: "Modifying files in \$HOME" };
 129|     }
 130|   }
 131| 
 132|   return { safe: true };
 133| }
