  98| async function interactive(existingMessages?: ChatMessage[]): Promise<void> {
  99|   const config = getConfig();
 100| 
 101|   // Build initial system prompt
 102|   const systemContent = await buildSystemContent(config, Deno.cwd());
 103| 
 104|   let messages: ChatMessage[];
 105|   if (existingMessages) {
 106|     messages = existingMessages;
 107|     // Update system prompt with current config
 108|     if (messages[0]?.role === "system") {
 109|       messages[0].content = systemContent;
 110|     }
 111|   } else {
 112|     messages = [
 113|       { role: "system", content: systemContent },
 114|     ];
 115|   }
 116| 
 117|   printBanner(config);
 118| 
 119|   const encoder = new TextEncoder();
 120|   const decoder = new TextDecoder();
 121|   let stdinBuffer = "";
 122| 
 123|   async function readLine(promptStr: string): Promise<string | null> {
 124|     const nlIndex = stdinBuffer.indexOf("\n");
 125|     if (nlIndex !== -1) {
 126|       const line = stdinBuffer.substring(0, nlIndex);
 127|       stdinBuffer = stdinBuffer.substring(nlIndex + 1);
 128|       return line.replace(/\r$/, "");
 129|     }
 130| 
 131|     await Deno.stdout.write(encoder.encode(promptStr));
 132| 
 133|     const buf = new Uint8Array(4096);
 134|     while (true) {
 135|       const n = await Deno.stdin.read(buf);
 136|       if (n === null) {
 137|         if (stdinBuffer.length > 0) {
 138|           const line = stdinBuffer;
 139|           stdinBuffer = "";
 140|           return line;
 141|         }
 142|         return null;
 143|       }
 144| 
 145|       stdinBuffer += decoder.decode(buf.subarray(0, n));
 146| 
 147|       const nlIdx = stdinBuffer.indexOf("\n");
 148|       if (nlIdx !== -1) {
 149|         const line = stdinBuffer.substring(0, nlIdx);
 150|         stdinBuffer = stdinBuffer.substring(nlIdx + 1);
 151|         return line.replace(/\r$/, "");
 152|       }
 153|     }
 154|   }
 155| 
 156|   // askUser callback for interactive mode
 157|   async function askUserCallback(question: string): Promise<string> {
 158|     console.error(`\n${colorize("💬", C.cyan)} ${bold("Agent asks:")} ${question}`);
 159|     const answer = await readLine(`${colorize("❯❯ ", C.cyan)}`);
 160|     return answer?.trim() ?? "";
 161|   }
 162| 
 163|   // Multi-line input support
 164|   async function readMultiLine(): Promise<string | null> {
 165|     const lines: string[] = [];
 166|     let firstLine = true;
 167| 
 168|     while (true) {
 169|       const promptStr = firstLine
 170|         ? colorize("❯ ", C.cyan)
 171|         : colorize("│ ", dim(""));
 172| 
 173|       const line = await readLine(promptStr);
 174|       firstLine = false;
 175| 
 176|       if (line === null) {
 177|         // EOF
 178|         return lines.length > 0 ? lines.join("\n") : null;
 179|       }
 180| 
 181|       // Empty line on first prompt = skip
 182|       if (lines.length === 0 && line.trim() === "") {
 183|         return "";
 184|       }
 185| 
 186|       // Check for termination: \e on its own line (backslash + 'e')
 187|       if (line.trim() === "\\e") {
 188|         return lines.join("\n");
 189|       }
 190| 
 191|       lines.push(line);
 192|     }
 193|   }
 194| 
 195|   console.error(dim("Type \\e on a new line to submit multi-line input. /help for commands."));
 196|   console.error("");
 197| 
 198|   while (true) {
 199|     const input = await readMultiLine();
 200|     if (input === null) break;
 201| 
 202|     const trimmed = input.trim();
 203| 
 204|     // Handle special commands
